 static String translate(String lang,String value){
  int i=lang.equals("hi")?0:lang.equals("es")?1:lang.equals("fr")?2:lang.equals("de")?3:-1;
  if(i<0)return value;
  String[] match=TEXT.get(value);
  return match==null?value:match[i];
 }
